const koreanHolidays={'2026-01-01':'신정','2026-02-16':'설날 연휴','2026-02-17':'설날','2026-02-18':'설날 연휴','2026-03-01':'삼일절','2026-03-02':'삼일절 대체공휴일','2026-05-05':'어린이날','2026-05-24':'부처님오신날','2026-05-25':'부처님오신날 대체공휴일','2026-06-06':'현충일','2026-08-15':'광복절','2026-08-17':'광복절 대체공휴일','2026-09-24':'추석 연휴','2026-09-25':'추석','2026-09-26':'추석 연휴','2026-10-03':'개천절','2026-10-05':'개천절 대체공휴일','2026-10-09':'한글날','2026-12-25':'성탄절'};document.head.insertAdjacentHTML('beforeend','<style>.holiday{background:#fff0f1!important;color:#c95252!important;position:relative}.holiday:before{content:attr(data-holiday);display:block;font-size:8px;position:absolute;right:5px;bottom:4px;color:#d7777c}</style>');setInterval(()=>Object.entries(koreanHolidays).forEach(([date,name])=>{let day=document.querySelector(`.day[data-date="${date}"]`);if(day){day.classList.add('holiday');day.dataset.holiday=name}}),250);
document.head.insertAdjacentHTML('beforeend','<style>.vacation-day:before{content:"휴가";position:absolute;right:5px;bottom:4px;font-size:8px;color:#d7777c}.vacation-day{position:relative}</style>');setInterval(()=>{document.querySelectorAll('.day[data-date]').forEach(day=>{let date=day.dataset.date,vacation=db.tasks.some(t=>t.vacation&&(t.date===date||(t.endDate&&t.date<=date&&t.endDate>=date)));day.classList.toggle('vacation-day',vacation);document.querySelectorAll('.event').forEach(event=>{let title=event.querySelector('span')?.textContent;if(db.tasks.some(t=>t.vacation&&t.title===title))event.style.display='none'})})},250);
setInterval(()=>document.querySelectorAll('.event').forEach(event=>{let box=event.querySelector('.calendar-check'),system=/ - (출고|ETD|ETA)$/.test(event.textContent.trim());if(box)box.style.display=system?'none':'inline-block'}),250);
setInterval(()=>{document.querySelectorAll('.task [data-done]').forEach(box=>{if(db.tasks.find(t=>t.id===box.dataset.done)?.vacation)box.closest('.task').style.display='none'});document.querySelectorAll('.calendar .event').forEach(event=>{if(event.textContent.trim().includes('휴가'))event.style.display='none'})},250);
setInterval(()=>document.querySelectorAll('.calendar .event').forEach(event=>{if(event.textContent.trim().includes('휴가'))event.style.cssText='display:none!important;height:0!important;margin:0!important;padding:0!important'}),100);
new MutationObserver(()=>document.querySelectorAll('.calendar .event').forEach(event=>{if(event.textContent.trim().includes('휴가'))event.remove()})).observe($('#calendarGrid'),{childList:true,subtree:true});
$('#shipmentSearch')?.remove();
let paymentCheckSnapshot='';setInterval(()=>{let next=db.ships.map(s=>`${s.id}:${!!s.done?.['입금 확인']}`).join('|');if(next!==paymentCheckSnapshot){paymentCheckSnapshot=next;render()}},300);
function tasks(target,a){a=a.filter(t=>!t.vacation);$(target).innerHTML=a.length?a.map(t=>`<label class="task"><input type="checkbox" data-done="${t.id}"><span>${esc(t.title)}<small>${t.date}</small></span><select data-status="${t.id}"><option value=""></option><option value="ing">~ing</option><option value="done">완료</option></select></label>`).join(''):'<small>등록된 할 일이 없습니다.</small>'}
setInterval(()=>{let ym=`${month.getFullYear()}-${String(month.getMonth()+1).padStart(2,'0')}`,el=$('#monthShipCount');if(el)el.textContent=db.ships.filter(s=>s.etd?.startsWith(ym)).length},250);
function ships(){let g=$('#filter').value,selectedMonth=$('#shipmentMonth').value,arr=db.ships.filter(s=>!selectedMonth||s.etd?.startsWith(selectedMonth)).sort((a,b)=>String(a[g]||'').localeCompare(String(b[g]||''))),today=iso(new Date());$('#shipmentList').innerHTML=arr.map(s=>{let boxes=Object.values(s.layout||{}).flat(),pct=boxes.length?Math.round(boxes.filter(name=>s.done?.[name]).length/boxes.length*100):0,parcel=!s.dispatch?7:today<s.dispatch?7:today===s.dispatch?27:!s.etd||today<s.etd?50:!s.eta||today<s.eta?92:97,where=!s.dispatch?'출고일 미정':today<s.dispatch?'출고 대기':today===s.dispatch?'창고 출고':!s.etd||today<s.etd?'선적 준비 중':!s.eta||today<s.eta?'항해 중':'도착 예정';return `<article class="shipment"><div><div class="ship-name">${esc(s.product)}${s.volume?` <span class="volume">(${esc(s.volume)})</span>`:''}<button class="info-edit" data-edit="${s.id}" aria-label="선적 정보 수정" title="선적 정보 수정">✎</button></div><div class="sub">${esc(s.country)} · ${esc(s.port)}${s.payment?`<br>결제 조건 · ${esc(s.payment)}`:''}</div></div><div class="dates">출고 ${dateWithDay(s.dispatch)}<br>ETD ${dateWithDay(s.etd)}<br>ETA ${dateWithDay(s.eta)}</div><div class="progress"><div class="progress-label"><small>업무 진행</small><strong>${pct}%</strong></div><div class="status-track"><b style="width:${pct}%"></b><i style="left:${Math.max(5,pct)}%" data-emoji="${s.id}" title="진행 이모지 변경">${s.progressEmoji||'🐣'}</i></div><div class="route" style="--parcel:${parcel}%"><span class="warehouse">🏭</span><small>${where}</small><span class="ship">🚢</span><i class="parcel">📦</i></div></div><div class="key-tasks">${['견적 생성','오더 번호','납품 번호','선적 문서','IP 관리 번호'].map(k=>`<label>${k}<input data-front="${k}" data-ship="${s.id}" value="${esc(s.fields[k]||'')}"></label>`).join('')}<button class="open" data-open="${s.id}" aria-label="업무 체크리스트 열기" title="업무 체크리스트 열기">→</button></div></article>`}).join('')||'<small>선택한 ETD 월의 선적건이 없습니다.</small>'}
function taskModal(t={}){let f=$('#taskForm');f.reset();f.dataset.id=t.id||'';Object.entries(t).forEach(([k,v])=>f.elements[k]&&(f.elements[k].value=v));let del=f.querySelector('[data-delete-task]');if(!del){del=document.createElement('button');del.type='button';del.dataset.deleteTask='';del.textContent='삭제';f.querySelector('.actions').prepend(del)}del.hidden=!t.id;del.onclick=()=>{if(!t.id)return;let remove=future=>{db.tasks=db.tasks.filter(x=>future?!(x.repeatGroup===t.repeatGroup&&x.date>=t.date):x.id!==t.id);save();$('#taskDialog').close();render()};if(!t.repeatGroup){if(confirm('이 일정을 삭제할까요?'))remove(false);return}let d=document.createElement('dialog');d.innerHTML='<h2>반복 일정 삭제</h2><p>삭제 범위를 선택하세요.</p><div class="actions"><button type="button" data-one>이 일정만</button><button type="button" class="primary" data-future>이후 일정도 삭제</button><button type="button" class="cancel">취소</button></div>';document.body.append(d);d.showModal();d.addEventListener('click',e=>{if(e.target.dataset.one){d.close();remove(false)}if(e.target.dataset.future){d.close();remove(true)}if(e.target.classList.contains('cancel'))d.close()});d.addEventListener('close',()=>d.remove())};$('#taskDialog').showModal()}
document.addEventListener('click',e=>{let key=e.target.dataset.auto;if(!key||!confirm('이 자동 일정을 캘린더에서 숨길까요?'))return;db.hiddenCalendarEvents=[...(db.hiddenCalendarEvents||[]),key];save();render()});
function detail(s){let d=document.createElement('dialog');d.className='detail-modal';let paint=()=>d.innerHTML=`<div class="panel-head"><h2>${esc(s.product)}${s.volume?` ${esc(s.volume)}`:''} (${esc(s.port||'도착항 미정')}) 업무 체크리스트</h2><button class="close">×</button></div><div class="check-columns">${Object.entries(s.layout).map(([c,a])=>`<section class="work-col" data-col="${c}"><h3>${c}<button data-add="${c}">＋</button></h3>${a.map(x=>`<div class="work-row" draggable="true" data-item="${x}"><input type="checkbox" data-check="${x}" ${s.done[x]?'checked':''}><span data-title="${x}">${x}</span>${link[x]?`<input data-link="${link[x]}" value="${esc(s.fields[link[x]]||'')}" placeholder="입력">`:''}</div>`).join('')}</section>`).join('')}</div><label>Memo<textarea class="memo">${esc(s.memo||'')}</textarea></label><div class="actions"><button data-default>제품 디폴트로 저장하기</button></div>`;paint();document.body.append(d);d.showModal();let moving;d.addEventListener('dragstart',e=>moving=e.target.closest('.work-row')?.dataset.item);d.addEventListener('dragover',e=>{if(e.target.closest('.work-col'))e.preventDefault()});d.addEventListener('drop',e=>{let col=e.target.closest('.work-col'),before=e.target.closest('.work-row')?.dataset.item;if(!col||!moving)return;Object.values(s.layout).forEach(a=>{let i=a.indexOf(moving);if(i>=0)a.splice(i,1)});let a=s.layout[col.dataset.col],i=before?a.indexOf(before):-1;a.splice(i<0?a.length:i,0,moving);save();paint()});d.addEventListener('click',e=>{if(e.target.classList.contains('close'))d.close();if(e.target.dataset.add){let x=prompt('새 업무명');if(x){s.layout[e.target.dataset.add].push(x);save();paint()}}if(e.target.dataset.default){db.defaults[s.product]=structuredClone(s.layout);save();e.target.textContent='저장됨'}if(e.target.dataset.title){let name=e.target.dataset.title,edit=document.createElement('dialog');edit.innerHTML=`<form><h2>${name}</h2><label>마감일<input type="date" name="date"></label><div class="actions"><button type="button" data-delete>삭제</button><button class="primary">저장</button></div></form>`;document.body.append(edit);edit.showModal();edit.querySelector('form').onsubmit=x=>{x.preventDefault();let date=new FormData(x.target).get('date');db.tasks.push({id:uid(),title:`${s.country} ${s.product} - ${name}`,date,color:'pink',status:'',shipment:s.id});save();render();edit.remove()};edit.querySelector('[data-delete]').onclick=()=>{Object.values(s.layout).forEach(a=>{let i=a.indexOf(name);if(i>=0)a.splice(i,1)});save();edit.remove();paint()}}});d.addEventListener('change',e=>{if(e.target.dataset.check){s.done[e.target.dataset.check]=e.target.checked;save()}if(e.target.dataset.link){s.fields[e.target.dataset.link]=e.target.value;save();document.querySelectorAll(`[data-front="${e.target.dataset.link}"],[data-link="${e.target.dataset.link}"]`).forEach(x=>{if(x!==e.target)x.value=e.target.value})}if(e.target.classList.contains('memo')){s.memo=e.target.value;save()}});d.addEventListener('close',()=>d.remove())}
$('#addTask').onclick=()=>taskModal();$('#addShipment').onclick=()=>{$('#shipmentForm').reset();$('#shipmentDialog').showModal()};document.querySelectorAll('.close,.cancel').forEach(b=>b.onclick=()=>b.closest('dialog').close());$('#taskForm').onsubmit=e=>{e.preventDefault();let v=Object.fromEntries(new FormData(e.target)),old=db.tasks.find(t=>t.id===e.target.dataset.id);old?Object.assign(old,v):db.tasks.push({id:uid(),...v,status:''});save();$('#taskDialog').close();render()};$('#shipmentForm').onsubmit=e=>{e.preventDefault();let v=Object.fromEntries(new FormData(e.target)),def=db.defaults[v.product];db.ships.push({id:uid(),...v,fields:{},done:{},memo:'',layout:structuredClone(def||base)});save();$('#shipmentDialog').close();render()};document.addEventListener('click',e=>{if(e.target.dataset.task)taskModal(db.tasks.find(t=>t.id===e.target.dataset.task));if(e.target.dataset.open)detail(db.ships.find(s=>s.id===e.target.dataset.open))});document.addEventListener('change',e=>{if(e.target.dataset.done){let t=db.tasks.find(t=>t.id===e.target.dataset.done);t.status=e.target.checked?'done':'';save();render()}if(e.target.dataset.status){let t=db.tasks.find(t=>t.id===e.target.dataset.status);t.status=e.target.value;save();render()}if(e.target.dataset.front){let s=db.ships.find(s=>s.id===e.target.dataset.ship);s.fields[e.target.dataset.front]=e.target.value;save()}});$('#prevMonth').onclick=()=>{month.setMonth(month.getMonth()-1);render()};$('#nextMonth').onclick=()=>{month.setMonth(month.getMonth()+1);render()};$('#filter').onchange=ships;setInterval(()=>$('#clock').textContent=new Intl.DateTimeFormat('ko-KR',{dateStyle:'medium',timeStyle:'short'}).format(new Date()),1000);render();
